"""Working demo for this book record: full reader + HTML exporter.
Run:  python3 book_demo.py              (prints the whole book)
      python3 book_demo.py 3            (prints chapter 3 only)
      python3 book_demo.py search WORD  (finds WORD across chapters)
      python3 book_demo.py html         (writes book.html)
"""
import json, sys, html as _h

BOOK = {'title': 'The Shadow of the necromancer Sylas', 'author': 'Signature original', 'genre': 'Enchanted Kingdoms', 'chapters': [{'n': 1, 'title': 'The Call', 'text': "At the first standing stone, Kael Windrider found the mark — the ancient rune of the bearers of the Crown of Thorns. It warmed under their hand. The quest, it seemed, had been waiting.\n\nthe wizard Old Fenwick arrived with a pack, a sword, and no patience for goodbyes. 'You're the one the songs mean,' the wizard Old Fenwick said. 'the Crown of Thorns chose you. Don't argue with songs.'\n\nThey left the Whispering Woods at dusk, the road winding into the unknown. Behind them, lights went out one by one as the necromancer Sylas's shadow spread. Ahead: everything."}, {'n': 2, 'title': 'Trials of the Road', 'text': "On the seventh night, Kael Windrider found the Crown of Thorns's trail — a shimmer in the air, a song half-heard. It was close now. And the necromancer Sylas knew they were coming.\n\nAt the moonwell they met a seer who spoke of the Crown of Thorns: 'It is not a weapon,' she said, 'though it can kill. It is not a shield, though it can save. It is a promise — and promises are the heaviest magic.'\n\nThey were ambushed by the necromancer Sylas's riders at the enchanted glade. Kael Windrider fought with a mithril blade borrowed from the wizard Old Fenwick, and learned that bravery is mostly refusing to run at the right moment."}, {'n': 3, 'title': 'The Descent', 'text': "To reach the Crown of Thorns, they had to descend into the necromancer Sylas's domain: a fortress of black glass where the sun never shone. the wizard Old Fenwick picked the locks; Kael Windrider carried the light — a single coal of hope in the dark.\n\nthe Crown of Thorns blazed at Kael Windrider's touch, recognizing its bearer. Power flooded through them — and with it, the terrible knowledge of its price. Every magic, the seer had said, is a promise. This one demanded everything.\n\nThey found the Crown of Thorns in the vault of whispers, guarded by the dragon Karthax. The beast spoke: 'Take it, little bearer, if you can answer: what is stronger than dragonfire?' Kael Windrider answered: 'hope is the strongest magic.' The dragon bowed and let them pass."}, {'n': 4, 'title': 'The Price', 'text': "Kael Windrider did not hesitate. They laid the Crown of Thorns on the wizard Old Fenwick's chest, and the light went into the wound, and the wound closed — and the Crown of Thorns went dark and cold. The quest's great weapon, spent on one life.\n\nThey escaped the fortress by griffon, the Crown of Thorns burning like a small sun. But the wizard Old Fenwick was wounded, and the wound festered with dark magic. The healers said only the Crown of Thorns itself could cure it — at the cost of its power.\n\nthe wizard Old Fenwick woke and wept to see it. 'The prophecy—' they began. Kael Windrider said: 'Prophecies are poems, not orders.' But the army of the necromancer Sylas was coming, and they had no magic left."}, {'n': 5, 'title': 'The Breaking of the Dark', 'text': "The army of the dark broke and ran. the Whispering Woods was free. Kael Windrider stood in the sudden silence holding the Crown of Thorns, which was only a crystal again — but a crystal that had kept its promise.\n\nThen Kael Windrider remembered the seer's words and the dragon's riddle, and did the last thing the necromancer Sylas expected: Kael Windrider offered mercy. 'Yield,' Kael Windrider said, 'and live.' the necromancer Sylas laughed — and in that laugh, the dark wavered.\n\nKael Windrider fought with the mithril blade and no magic at all — only skill, and love of the Whispering Woods, and the wizard Old Fenwick shouting from the lines. the necromancer Sylas fought with hate and sorcery, and for a long while hate seemed stronger."}, {'n': 6, 'title': 'The Return', 'text': 'the Crown of Thorns was set in the great hall, where children touch it for luck. It never blazed again — but on dark nights, travelers swear it glows faintly, like a coal that remembers fire.\n\nAnd the choice, the songs say, is always the same: hope is the strongest magic. In the Whispering Woods and everywhere, forever.\n\nThey came home to the Whispering Woods in spring, when the orchards bloomed. The songs had already arrived ahead of them, as songs do, and every verse was wrong in the details and right in the heart.'}]}

def word_count():
    return sum(len(c["text"].split()) for c in BOOK["chapters"])

def print_book(ch=None):
    print("=" * 64)
    print(BOOK["title"].upper(), "\nby", BOOK["author"], "-", BOOK["genre"])
    print("=" * 64)
    for c in BOOK["chapters"]:
        if ch and c["n"] != ch:
            continue
        print("\n\nCHAPTER %d: %s\n%s" % (c["n"], c["title"], "-" * 40))
        print(c["text"])
    print("\n[%d words, %d chapters — complete]" % (word_count(), len(BOOK["chapters"])))

def search(word):
    w = word.lower()
    for c in BOOK["chapters"]:
        for i, para in enumerate(c["text"].split("\n\n")):
            if w in para.lower():
                print("[ch %d, para %d] %s..." % (c["n"], i + 1, para[:160].replace("\n", " ")))

def write_html(path="book.html"):
    parts = ["<html><head><meta charset='utf-8'><title>%s</title></head><body>" % _h.escape(BOOK["title"])]
    parts.append("<h1>%s</h1><p><i>by %s — %s</i></p>" % (_h.escape(BOOK["title"]), _h.escape(BOOK["author"]), _h.escape(BOOK["genre"])))
    for c in BOOK["chapters"]:
        parts.append("<h2>Chapter %d: %s</h2>" % (c["n"], _h.escape(c["title"])))
        for para in c["text"].split("\n\n"):
            parts.append("<p>%s</p>" % _h.escape(para))
    parts.append("</body></html>")
    open(path, "w").write("\n".join(parts))
    print("wrote", path)

if __name__ == "__main__":
    a = sys.argv[1:]
    if a and a[0] == "html":
        write_html()
    elif len(a) >= 2 and a[0] == "search":
        search(a[1])
    elif a and a[0].isdigit():
        print_book(int(a[0]))
    else:
        print_book()

